const sq = (s) => "'" + s.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n') + "'";
const opStr = (op) => {
  let s = '  {\n';
  for (const k of ['f', 'find', 'rep', 'n']) {
    if (op[k] !== undefined) s += '    ' + k + ': ' + (typeof op[k] === 'number' ? op[k] : sq(op[k])) + ',\n';
  }
  return s + '  },';
};
